// Confetti library - simple implementation
(function(global) {
  var confetti = function(options) {
    options = options || {};
    var particleCount = options.particleCount || 50;
    var angle = options.angle || 90;
    var spread = options.spread || 45;
    var startVelocity = options.startVelocity || 45;
    var decay = options.decay || 0.95;
    var gravity = options.gravity || 1;
    var drift = options.drift || 0;
    var colors = options.colors || ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
    
    var canvas = document.createElement('canvas');
    canvas.style.position = 'fixed';
    canvas.style.top = '0';
    canvas.style.left = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.pointerEvents = 'none';
    canvas.style.zIndex = '9999';
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    document.body.appendChild(canvas);
    
    var ctx = canvas.getContext('2d');
    var particles = [];
    
    // Create particles
    for (var i = 0; i < particleCount; i++) {
      var particle = {
        x: canvas.width / 2,
        y: canvas.height / 2,
        vx: (Math.random() - 0.5) * startVelocity,
        vy: -Math.random() * startVelocity,
        color: colors[Math.floor(Math.random() * colors.length)],
        life: 1,
        size: Math.random() * 4 + 2
      };
      particles.push(particle);
    }
    
    function animate() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      for (var i = particles.length - 1; i >= 0; i--) {
        var p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += gravity;
        p.vx *= decay;
        p.vy *= decay;
        p.life -= 0.02;
        
        if (p.life <= 0) {
          particles.splice(i, 1);
        } else {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.fillRect(p.x, p.y, p.size, p.size);
        }
      }
      
      if (particles.length > 0) {
        requestAnimationFrame(animate);
      } else {
        document.body.removeChild(canvas);
      }
    }
    
    animate();
  };
  
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = confetti;
  } else {
    global.confetti = confetti;
  }
})(typeof window !== 'undefined' ? window : typeof global !== 'undefined' ? global : typeof self !== 'undefined' ? self : this);
